import{_ as n,H as a,f as p,i as e}from"./chunks/framework.BH2BK_3i.js";const r=JSON.parse('{"title":"35 | Linux文件系统（一）：Linux如何存放文件？","description":"","frontmatter":{},"headers":[{"level":2,"title":"建立虚拟硬盘","slug":"建立虚拟硬盘","link":"#建立虚拟硬盘","children":[]},{"level":2,"title":"Ext3 文件系统结构","slug":"ext3-文件系统结构","link":"#ext3-文件系统结构","children":[{"level":3,"title":"Ext3 文件系统的超级块","slug":"ext3-文件系统的超级块","link":"#ext3-文件系统的超级块","children":[]},{"level":3,"title":"Ext3 文件系统的块组描述符表","slug":"ext3-文件系统的块组描述符表","link":"#ext3-文件系统的块组描述符表","children":[]},{"level":3,"title":"Ext3 文件系统的位图块","slug":"ext3-文件系统的位图块","link":"#ext3-文件系统的位图块","children":[]},{"level":3,"title":"Ext3 文件系统的 inode 节点","slug":"ext3-文件系统的-inode-节点","link":"#ext3-文件系统的-inode-节点","children":[]},{"level":3,"title":"Ext3 文件系统的目录项","slug":"ext3-文件系统的目录项","link":"#ext3-文件系统的目录项","children":[]},{"level":3,"title":"重点回顾","slug":"重点回顾","link":"#重点回顾","children":[]}]},{"level":2,"title":"思考题","slug":"思考题","link":"#思考题","children":[]}],"relativePath":"计算机基础实战课/35｜Linux文件系统（一）：Linux如何存放文件？.md","filePath":"计算机基础实战课/35｜Linux文件系统（一）：Linux如何存放文件？.md","lastUpdated":1795560006000}'),i={name:"计算机基础实战课/35｜Linux文件系统（一）：Linux如何存放文件？.md"};function l(t,s,_,c,o,d){return a(),p("div",null,[...s[0]||(s[0]=[e(`<h1 id="_35-linux文件系统-一-linux如何存放文件" tabindex="-1">35 | Linux文件系统（一）：Linux如何存放文件？ <a class="header-anchor" href="#_35-linux文件系统-一-linux如何存放文件" aria-label="Permalink to &quot;35 | Linux文件系统（一）：Linux如何存放文件？&quot;">​</a></h1><p>你好，我是 LMOS。</p><p>上一节课，我们一起了解了什么是文件和文件系统。接下来的两节课，我们继续深入学习Linux 上的一个具体的文件系统——Ext3，搞清楚了文件究竟是如何存放的。</p><p>这节课我会带你建立一个虚拟硬盘，并在上面建立一个文件系统。对照代码实例，相信你会对Ext3 的结构有一个更深入的认识。课程配套代码，你可以从这里下载。话不多说，我们开始吧。</p><h2 id="建立虚拟硬盘" tabindex="-1">建立虚拟硬盘 <a class="header-anchor" href="#建立虚拟硬盘" aria-label="Permalink to &quot;建立虚拟硬盘&quot;">​</a></h2><p>要想建立文件系统就得先有硬盘，我们直接用真正的物理硬盘非常危险，搞不好数据就会丢失。所以，这里我们选择虚拟硬盘，在这个虚拟硬盘上操作，这样怎么折腾都不会有事。</p><p>其实我们是用 Linux 下的一个文件来模拟硬盘的，写入硬盘的数据只是写入了这个文件中。所以建立虚拟硬盘，就相当于生成一个对应的文件。比如，我们要建立一个 100MB 的硬盘，就意味着我们要生成 100MB 的大文件。</p><p>下面我们用 Linux 下的 dd 命令（用指定大小的块拷贝一个文件，并在拷贝的同时进行指定的转换）生成 100MB 的纯二进制的文件（就是向 1～100M 字节的文件里面填充为 0 ），代码如下所示：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>dd bs=512 if=/dev/zero of=hd.img count=204800</span></span>
<span class="line"><span>;bs:表示块大小，这里是512字节</span></span>
<span class="line"><span>;if：表示输入文件，/dev/zero就是Linux下专门返回0数据的设备文件，读取它就返回0</span></span>
<span class="line"><span>;of：表示输出文件，即我们的硬盘文件</span></span>
<span class="line"><span>;count：表示输出多少块</span></span></code></pre></div><p>下面我们就要在虚拟硬盘上建立文件系统了，所谓建立文件系统就是对虚拟硬盘放进行格式化。可是，问题来了——虚拟硬盘毕竟是个文件，如何让 Linux 在一个文件上建立文件系统呢？</p><p>这个问题我们要分成两步来解决。</p><p>第一步，把虚拟硬盘文件变成 Linux 下的回环设备，让 Linux 以为这是个设备。下面我们用losetup 命令，将 hd.img 这个文件变成 Linux 的回环设备，代码如下：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> losetup</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /dev/loop0</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> hd.img</span></span></code></pre></div><p>第二步，由于回环设备就是 Linux 下的块设备，用户可以将其看作是硬盘、光驱或软驱等设备，并且可以用 mount 命令把该回环设备挂载到特定目录下。这样我们就可以用 Linux 下的mkfs.ext3 命令，把这个 /dev/loop0 回环块设备格式化，进而格式化 hd.img 文件，在里面建立 Ext3 文件系统。</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> mkfs.ext3</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -q</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /dev/loop0</span></span></code></pre></div><p>需要注意的是，loop0 可能已经被占用了，我们可以使用 loop1、loop2 等，你需要根据自己电脑的情况处理。</p><p>我们可以用 mount 命令将 hd.img 挂载到特定的目录下，如果命令执行成功，就能验证我们虚拟硬盘上的文件系统成功建立。命令如下所示：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> mount</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -o</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> loop</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ./hd.img</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ./hdisk/</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> ;</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">挂载硬盘文件</span></span></code></pre></div><p>这行代码的作用是，将 hd.img 这个文件使用 loop 模式挂载在 ./hdisk/ 目录之下，通过这个hdisk 目录，就能访问到 hd.img 虚拟硬盘了。并且，我们还可以用常用的 mkdir、touch 命令在这个虚拟硬盘中建立目录和文件。</p><h2 id="ext3-文件系统结构" tabindex="-1">Ext3 文件系统结构 <a class="header-anchor" href="#ext3-文件系统结构" aria-label="Permalink to &quot;Ext3 文件系统结构&quot;">​</a></h2><p>我们建好了硬盘，对其进行了格式化，也在上面建立了 Ext3 文件系统。下面我们就来研究一下 Ext3 文件系统的结构。</p><p>Ext3 文件系统的全称是 Third extended file system，已经有 20 多年的历史了，是一种古老而成熟的文件系统。Ext3 在 Ext2 基础上加入了日志机制，也算是对 Ext2 文件系统的扩展，并且也能兼容 Ext2。Ext3 是在发布 Linux2.4.x 版本时加入的，支持保存上 TB 的文件，保存的文件数量由硬盘容量决定，还支持高达 255 字节的文件名。</p><p>Ext3 的内部结构是怎样的呢？Ext3 将一个硬盘分区分为大小相同的储存块，每个储存块可以是 2 个扇区、4 个扇区、8 个扇区，分别对应大小为 1KB、2KB、4KB。</p><p>所有的储存块又被划分为若干个块组，每个块组中的储存块数量相同。每个块组前面若干个储存块中，依次放着：超级块、块组描述表、块位图、inode 节点位图、inode 节点表、数据块区。需要注意的是，超级块和块组描述表是全局性的，在每个块组中它们的数据是相同的。</p><p>我再帮你画一个逻辑结构图，你就容易理解了，如下所示：</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E8%AE%A1%E7%AE%97%E6%9C%BA%E5%9F%BA%E7%A1%80%E5%AE%9E%E6%88%98%E8%AF%BE/images/35/1.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E8%AE%A1%E7%AE%97%E6%9C%BA%E5%9F%BA%E7%A1%80%E5%AE%9E%E6%88%98%E8%AF%BE/images/35/1.png" alt=""></a></p><p>上图中，第 1 个储存块是用于安装引导程序，或者也可以保留不使用的。超级块占用一个储存块，在第 2 个储存块中，即储存块 1，储存块的块号是针对整个分区编码的，从 0 开始。其中的块组描述符表、块位图、inode 节点位图、inode 节点表的占用大小，是根据块组多少以及块组的大小动态计算的。</p><p>下面我们分别讨论这些重要结构。</p><h3 id="ext3-文件系统的超级块" tabindex="-1">Ext3 文件系统的超级块 <a class="header-anchor" href="#ext3-文件系统的超级块" aria-label="Permalink to &quot;Ext3 文件系统的超级块&quot;">​</a></h3><p>我们首先要探讨的是 Ext3 文件系统的超级块，它描述了 Ext3 的整体信息，例如有多少个inode 节点、多少个储存块、储存块大小、第一个数据块号是多少，每个块组多少个储存块等。</p><p>Ext3 文件系统的超级块存放在该文件系统所在分区的 2 号扇区，占用两个扇区。当储存块的大小不同时，超级块所在块号是不同的。</p><p>比如说，当储存块大小为 1KB 时，0 号块是引导程序或者保留储存块，超级块起始于 1 号块储存；当块大小为 2KB 时，超级块起始于 0 号储存块，其位于 0 号储存块的后 1KB，前 1KB是引导程序或者保留；当储存块大小为 4KB 时，超级块也起始于 0 号储存块，其位于 0 号块的 1KB 处。总之，超级块位于相对于分区的 2 号~3 号扇区，这一点是固定的。</p><p>下面我们看一看用 C 语言定义的超级块，代码如下所示：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>struct ext3_super_block {</span></span>
<span class="line"><span> __le32  s_inodes_count;    //inode节点总数</span></span>
<span class="line"><span> __le32  s_blocks_count;    // 储存块总数</span></span>
<span class="line"><span> __le32  s_r_blocks_count;  // 保留的储存块数</span></span>
<span class="line"><span> __le32  s_free_blocks_count;// 空闲的储存块数</span></span>
<span class="line"><span>   __le32  s_free_inodes_count;// 空闲的inode节点数</span></span>
<span class="line"><span> __le32  s_first_data_block;  // 第一个数据储存块号</span></span>
<span class="line"><span> __le32  s_log_block_size;  // 储存块大小</span></span>
<span class="line"><span> __le32  s_log_frag_size;  // 碎片大小</span></span>
<span class="line"><span> __le32  s_blocks_per_group;  // 每块组包含的储存块数</span></span>
<span class="line"><span> __le32  s_frags_per_group;  // 每块组包含的碎片</span></span>
<span class="line"><span> __le32  s_inodes_per_group;  // 每块组包含的inode节点数</span></span>
<span class="line"><span> __le32  s_mtime;        // 最后挂载时间</span></span>
<span class="line"><span>   __le32  s_wtime;      // 最后写入时间</span></span>
<span class="line"><span> __le16  s_mnt_count;    // 挂载次数</span></span>
<span class="line"><span> __le16  s_max_mnt_count;  // 最大挂载次数</span></span>
<span class="line"><span> __le16  s_magic;      // 魔数</span></span>
<span class="line"><span> __le16  s_state;      // 文件系统状态</span></span>
<span class="line"><span> __le16  s_errors;      // 错误处理方式</span></span>
<span class="line"><span> __le16  s_minor_rev_level;  // 次版本号</span></span>
<span class="line"><span> __le32  s_lastcheck;    // 最后检查时间</span></span>
<span class="line"><span> __le32  s_checkinterval;  // 强迫一致性检查的最大间隔时间</span></span>
<span class="line"><span> __le32  s_creator_os;    // 建立文件系统的操作系统</span></span>
<span class="line"><span> __le32  s_rev_level;    // 主版本号</span></span>
<span class="line"><span> __le16  s_def_resuid;    // 默认用户保留储存块</span></span>
<span class="line"><span> __le16  s_def_resgid;    // 默认用户组保留储存块</span></span>
<span class="line"><span> __le32  s_first_ino;    // 第一个非保留inode节点号</span></span>
<span class="line"><span> __le16   s_inode_size;    // inode节点大小</span></span>
<span class="line"><span> __le16  s_block_group_nr;  // 当前超级块所在块组</span></span>
<span class="line"><span> __le32  s_feature_compat;  // 兼容功能集</span></span>
<span class="line"><span> __le32  s_feature_incompat;  // 非兼容功能集</span></span>
<span class="line"><span> __le32  s_feature_ro_compat;// 只读兼容功能集</span></span>
<span class="line"><span> __u8  s_uuid[16];      // 卷的UUID（全局ID）</span></span>
<span class="line"><span> char  s_volume_name[16];  // 卷名</span></span>
<span class="line"><span> char  s_last_mounted[64];  // 文件系统最后挂载路径</span></span>
<span class="line"><span> __le32  s_algorithm_usage_bitmap; // 位图算法</span></span>
<span class="line"><span>     //省略了日志相关的字段</span></span>
<span class="line"><span>};</span></span></code></pre></div><p>以上的代码中我省略了日志和预分配的相关字段，而 __le16 __le32，在 x86 上就是 u16、u32 类型的数据。le 表示以小端字节序储存数据，定义成这样，是为了大小端不同的 CPU 可以使用相同文件系统，或者已经存在的文件系统的前提下，方便进行数据转换。</p><h3 id="ext3-文件系统的块组描述符表" tabindex="-1">Ext3 文件系统的块组描述符表 <a class="header-anchor" href="#ext3-文件系统的块组描述符表" aria-label="Permalink to &quot;Ext3 文件系统的块组描述符表&quot;">​</a></h3><p>接着我们来看看 Ext3 文件系统的块组描述符，里面存放着用来描述块组中的位图块起始块号、inode 节点表起始块号、空闲 inode 节点数、空闲储存块数等信息，文件系统中每个块组都有这样的一个块组描述符与之对应。所有的块组描述符集中存放，就形成了块组描述符表。</p><p>块组描述符表的起始块号位于超级块所在块号的下一个块，在整个文件系统中，存有很多块组描述符表的备份，存在的方式与超级块相同。</p><p>下面我们看一看用 C 语言定义的单个块组描述符结构，如下所示：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>struct ext3_group_desc</span></span>
<span class="line"><span>{</span></span>
<span class="line"><span> __le32  bg_block_bitmap;    // 该块组位图块起始块号</span></span>
<span class="line"><span> __le32  bg_inode_bitmap;    // 该块组inode节点位图块起始块号</span></span>
<span class="line"><span> __le32  bg_inode_table;      // 该块组inode节点表起始块号</span></span>
<span class="line"><span> __le16  bg_free_blocks_count;  // 该块组的空闲块</span></span>
<span class="line"><span> __le16  bg_free_inodes_count;  // 该块组的空闲inode节点数</span></span>
<span class="line"><span> __le16  bg_used_dirs_count;    // 该块组的目录计数</span></span>
<span class="line"><span> __u16  bg_pad;          // 填充</span></span>
<span class="line"><span> __le32  bg_reserved[3];      // 保留未用</span></span>
<span class="line"><span>};</span></span></code></pre></div><p>对照上述代码，我们可以看到，多个 ext3_group_desc 结构就形成了块组描述符表，而__le16 __le32 类型和超级块中的相同。如果想知道文件系统中有多少个块组描述符，可以通过超级块中总块数和每个块组的块数来进行计算。</p><h3 id="ext3-文件系统的位图块" tabindex="-1">Ext3 文件系统的位图块 <a class="header-anchor" href="#ext3-文件系统的位图块" aria-label="Permalink to &quot;Ext3 文件系统的位图块&quot;">​</a></h3><p>接下来要说的是 Ext3 文件系统的位图块，它非常简单，每个块组中有两种位图块：一种用来描述块组内每个储存块的分配状态，另一种用于描述 inode 节点的分配状态。</p><p>位图块中没有什么结构，就是位图数据，即块中的每个字节都有八个位。每个位表示一个相应对象的分配状态，该位为 0 时，表示相应对象为空闲可用状态，为 1 时则表示相应对象是占用状态。例如位图块中第一个字节，表示块组 0~7 号储存块的分配状态；第二个字节，表示块组 8~15 号储存块的分配状态 ……依次类推。位图块的块号可以从块组描述符中得到。</p><h3 id="ext3-文件系统的-inode-节点" tabindex="-1">Ext3 文件系统的 inode 节点 <a class="header-anchor" href="#ext3-文件系统的-inode-节点" aria-label="Permalink to &quot;Ext3 文件系统的 inode 节点&quot;">​</a></h3><p>接下来，我们再深入研究一下 inode 节点。上节课我们提过，inode 节点用来存放跟文件相关的所有信息，但是文件名称却不在 inode 节点之中，文件名称保存在文件目录项中。</p><p>inode 节点中包含了文件模式、文件链接数、文件大小、文件占用扇区数、文件的访问和修改的时间信息、文件的用户 ID、文件的用户组 ID、文件数据内容的储存块号等，这些重要信息也被称为文件的元数据。</p><p>那么，用 C 语言如何定义单个 inode 节点结构呢？代码如下所示：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>struct ext3_inode {</span></span>
<span class="line"><span> __le16  i_mode;    // 文件模式</span></span>
<span class="line"><span> __le16  i_uid;    // 建立文件的用户</span></span>
<span class="line"><span> __le32  i_size;    // 文件大小</span></span>
<span class="line"><span> __le32  i_atime;  // 文件访问时间</span></span>
<span class="line"><span> __le32  i_ctime;  // 文件建立时间</span></span>
<span class="line"><span> __le32  i_mtime;  // 文件修改时间</span></span>
<span class="line"><span> __le32  i_dtime;  // 文件删除时间</span></span>
<span class="line"><span> __le16  i_gid;    // 建立文件的用户组</span></span>
<span class="line"><span> __le16  i_links_count;  // 文件的链接数</span></span>
<span class="line"><span> __le32  i_blocks;  // 文件占用的储存块 */</span></span>
<span class="line"><span> __le32  i_flags;  // 文件标志</span></span>
<span class="line"><span> union {</span></span>
<span class="line"><span>   struct {</span></span>
<span class="line"><span>     __u32  l_i_reserved1;</span></span>
<span class="line"><span>   } linux1;</span></span>
<span class="line"><span>   struct {</span></span>
<span class="line"><span>     __u32  h_i_translator;</span></span>
<span class="line"><span>   } hurd1;</span></span>
<span class="line"><span>   struct {</span></span>
<span class="line"><span>     __u32  m_i_reserved1;</span></span>
<span class="line"><span>   } masix1;</span></span>
<span class="line"><span> } osd1;        //操作系统依赖1</span></span>
<span class="line"><span> __le32  i_block[EXT3_N_BLOCKS];// 直接块地址</span></span>
<span class="line"><span> __le32  i_generation;  // 文件版本</span></span>
<span class="line"><span> __le32  i_file_acl;  // 文件扩展属性块</span></span>
<span class="line"><span> __le32  i_dir_acl;  // 目录扩展属性块</span></span>
<span class="line"><span> __le32  i_faddr;  // 段地址</span></span>
<span class="line"><span> union {</span></span>
<span class="line"><span>   struct {</span></span>
<span class="line"><span>     __u8  l_i_frag;  //段号</span></span>
<span class="line"><span>     __u8  l_i_fsize;  //段大小</span></span>
<span class="line"><span>     __u16  i_pad1;</span></span>
<span class="line"><span>     __le16  l_i_uid_high;</span></span>
<span class="line"><span>     __le16  l_i_gid_high;</span></span>
<span class="line"><span>     __u32  l_i_reserved2;</span></span>
<span class="line"><span>   } linux2;</span></span>
<span class="line"><span>   struct {</span></span>
<span class="line"><span>     __u8  h_i_frag;  //段号</span></span>
<span class="line"><span>     __u8  h_i_fsize;  //段大小</span></span>
<span class="line"><span>     __u16  h_i_mode_high;</span></span>
<span class="line"><span>     __u16  h_i_uid_high;</span></span>
<span class="line"><span>     __u16  h_i_gid_high;</span></span>
<span class="line"><span>     __u32  h_i_author;</span></span>
<span class="line"><span>   } hurd2;</span></span>
<span class="line"><span>   struct {</span></span>
<span class="line"><span>     __u8  m_i_frag;  //段号</span></span>
<span class="line"><span>     __u8  m_i_fsize;  //段大小</span></span>
<span class="line"><span>     __u16  m_pad1;</span></span>
<span class="line"><span>     __u32  m_i_reserved2[2];</span></span>
<span class="line"><span>   } masix2;</span></span>
<span class="line"><span> } osd2;        //操作系统依赖2</span></span>
<span class="line"><span> __le16  i_extra_isize;</span></span>
<span class="line"><span> __le16  i_pad1;</span></span>
<span class="line"><span>};</span></span></code></pre></div><p>这就是 inode 节点，它包含文件的所有信息。文件的数据内容的储存块号保存在 i_block 中，这个 i_block 数组前十二元素保存的是 1~12 这 12 个储存块号，第十三个元素开始保存的是一级间接储存块块号、二级间接储存块块号、三级间接储存块块号。</p><p>那问题来了，什么是间接储存块？我给你画幅图，你就明白了。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E8%AE%A1%E7%AE%97%E6%9C%BA%E5%9F%BA%E7%A1%80%E5%AE%9E%E6%88%98%E8%AF%BE/images/35/2.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E8%AE%A1%E7%AE%97%E6%9C%BA%E5%9F%BA%E7%A1%80%E5%AE%9E%E6%88%98%E8%AF%BE/images/35/2.png" alt=""></a></p><p>由上图可知，一个 inode 节点中有 11 个直接储存块，其中存放的是块号，能直接索引 11 个储存块。</p><p>如果每个储存块大小是 1KB 的话，可以保存 11KB 的文件数据；当文件内容大于 11KB 时，就要用到一级间接储存块。</p><p>这时，一级间接储存块里的块号索引的储存块中不是文件数据，而是储存的指向储存块的块号，它可以储存 1024/4 个块号，即可索引 1024/4 个储存块。二级、三级间接块则依次类推，只不过级别更深，保存的块号就更多，能索引的储存块就更多，储存文件的数据量就更大。</p><h3 id="ext3-文件系统的目录项" tabindex="-1">Ext3 文件系统的目录项 <a class="header-anchor" href="#ext3-文件系统的目录项" aria-label="Permalink to &quot;Ext3 文件系统的目录项&quot;">​</a></h3><p>讲到这里，我们已经对 Ext3 文件系统若干结构都做了梳理，现在你应该对 Ext3 文件系统如何储存文件有了一定认识。</p><p>可是文件系统中还有许多文件目录，文件目录是怎么处理的呢？</p><p>Ext3 文件系统把目录当成了一种特殊的文件，即目录文件，目录文件有自己的 inode 节点，能读取其中数据。在目录文件的数据中，保存的是一系列目录项，目录项用来存放文件或者目录的 inode 节点号、目录项的长度、文件名等信息。</p><p>下面我们看一看，用 C 语言定义的单个目录项结构长什么样：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>#define EXT3_NAME_LEN 255</span></span>
<span class="line"><span>struct ext3_dir_entry {</span></span>
<span class="line"><span> __le32  inode;        // 对应的inode节点号</span></span>
<span class="line"><span> __le16  rec_len;      // 目录项长度</span></span>
<span class="line"><span> __u8  name_len;      // 文件名称长度</span></span>
<span class="line"><span> __u8  file_type;      // 文件类型：文件、目录、符号链接</span></span>
<span class="line"><span> char  name[EXT3_NAME_LEN];// 文件名</span></span>
<span class="line"><span>};</span></span></code></pre></div><p>目录项结构大小不是固定不变的，这是由于每个文件或者目录的名称，不一定是 255 个字符，一般情况下是少于 255 个字符，这就导致 name 数组不必占用完整的空间。所以目录项是动态变化，需要结构中的 rec_len 字段，才能知道目录项的真实大小。</p><h3 id="重点回顾" tabindex="-1">重点回顾 <a class="header-anchor" href="#重点回顾" aria-label="Permalink to &quot;重点回顾&quot;">​</a></h3><p>今天的课程我们就结束了，我们一起回顾一下学习的重点。</p><p>首先为了体验一下怎么建立文件系统，同时为了避免我们在物理硬盘的误操作导致丢失数据，所以我们用文件方式建立了一个虚拟硬盘，并在上面格式化了 Ext3 文件系统。</p><p>接着我们从逻辑上了解 Ext3 文件系统，重点了解了它的几个重要结构：超级块用于保存文件系统全局信息了；块组描述符用于表示硬盘的一个个块组；位图用于分配储存块和 inode 节点；inode 节点用于保存文件的元数据，还有文件数据块的块号；最后还有目录结构，用来存放者文件或者目录的 inode 节点号、目录项的长度、文件名等信息。</p><p>这节课的导图如下所示，供你参考：</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E8%AE%A1%E7%AE%97%E6%9C%BA%E5%9F%BA%E7%A1%80%E5%AE%9E%E6%88%98%E8%AF%BE/images/35/3.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E8%AE%A1%E7%AE%97%E6%9C%BA%E5%9F%BA%E7%A1%80%E5%AE%9E%E6%88%98%E8%AF%BE/images/35/3.png" alt=""></a></p><p>下节课我们继续聊聊怎么读取文件系统的文件，敬请期待。</p><h2 id="思考题" tabindex="-1">思考题 <a class="header-anchor" href="#思考题" aria-label="Permalink to &quot;思考题&quot;">​</a></h2><p>请问 Ext3 文件系统的超级块放在硬盘分区的第几个扇区中。</p><p>欢迎你在留言区记录自己的收获，或者向我提问。如果觉得这节课还不错，别忘了分享给身边的朋友。</p>`,72)])])}const u=n(i,[["render",l]]);export{r as __pageData,u as default};
